window.DAILY = {"generated_utc": "2026-11-23T09:11:56Z", "date_cn": "2026-11-23", "window_days": 3, "source": "arXiv OAI-PMH/API (cs.CV/cs.RO) · 热度加成: Hugging Face Daily Papers", "note": "所有条目直接来自 arXiv 元数据，未经人工或模型改写；预印本未经同行评审。", "tracks": {"slam": {"name": "SLAM 与状态估计", "papers": [{"id": "2611.27633", "title": "Instant-LIVO: Efficient LiDAR-Inertial-Visual Odometry with Compact Geometry and a Bounded Single-Reference-Frame Map", "authors": ["Xinrui Wang", "Ziwei Lan", "Wenbin He", "Mingjing Yang", "Yihan Zhang", "Yilin Liu", "Peiji Chen", "Wenxin Li", "Shuyi Jiang", "Yubin Lan", "Weiguang Yang"], "abstract": "LiDAR-Inertial-Visual Odometry (LIVO) is a fundamental technology for autonomous systems; however, deployment on resource-constrained platforms remains challenging due to physical limitations. This paper presents Instant-LIVO, a tightly coupled, high-speed, real-time LIVO system. The system introduces a compact geometric map based on spatial-hashed OctVox and accelerates local-neighborhood retrieval and plane fitting through cache-assisted heuristic staged K-nearest-neighbor searches. It also employs a bounded single-reference-frame visual map that adaptively updates the reference frame according to the tracking status, while using Schmidt-type uncertainty-aware photometric fusion to maintain the correlation between the reference pose and the current state. The system performs multisensor fusion through a sequential process consisting of IMU prediction, LiDAR geometric correction, and visual photometric correction. It was evaluated on 32 public benchmarks and custom datasets. While maintaining competitive accuracy on both X86 and ARM platforms, Instant-LIVO achieves average processing-speed improvements of approximately 2.3x and 2.1x, respectively, and reduces peak memory usage to approximately 1/20 and 1/13, respectively. The results demonstrate that the proposed method outperforms existing LIO and LIVO baselines in both accuracy and computational efficiency.The implementation is available at: https://github.com/Faker-0714/Instant-LIVO.git.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.27633"}, {"id": "2605.19257", "title": "PRISM-SLAM: Probabilistic Ray-Grounded Inference for Scale-aware Metric SLAM", "authors": ["Eunsoo Im", "Gyeonggwan Lee", "Seunghwan Hong", "Junghun Suh"], "abstract": "Monocular SLAM historically suffers from scale ambiguity and tracking failure in dynamic environments. While recent vision foundation models (VFMs) provide remarkable zero-shot depth priors, naively integrating these deterministic predictions ignores predictive uncertainty and frame-to-frame scale inconsistencies. We propose PRISM-SLAM, a real-time framework that rigorously integrates VFM priors into a structured Bayesian factor graph to achieve scale-aware, metric-consistent localization and mapping. Specifically, we introduce a Plücker Ray-Distance Factor to anchor monocular observations in absolute space within a globally consistent metric coordinate system, mathematically resolving scale drift by making the metric scale Fisher-identifiable. To handle environmental dynamics, we derive an epistemic uncertainty proxy from temporal depth consistency and formulate a Dynamic Scene Uncertainty Gating (DSUG) mechanism. This soft-gating approach probabilistically down-weights dynamic distractors without incurring the heavy computational overhead associated with traditional semantic segmentation masks. By employing a multi-process architecture that asynchronously processes VFM inference and geometric tracking, PRISM-SLAM provides verified metric output at 30 FPS using solely RGB input, bridging the gap between foundation models and real-world robotic applications. Evaluated on the TUM RGB-D and 7-Scenes benchmarks, PRISM-SLAM achieves a metric $SE(3)$ Absolute Trajectory Error (ATE) nearly identical to its oracle-aligned $Sim(3)$ error. This demonstrates that our system can produce deployment-ready metric trajectories by delivering robust metric SLAM solutions without any post-hoc scale correction. Project page: https://prismslam-cmd.github.io/prismslam_pr/", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2605.19257"}, {"id": "2611.27362", "title": "NormFlowSDE: Normalizing Flows for Amortized Bayesian State Estimation", "authors": ["Yi Zhang", "Lars Mikelsons"], "abstract": "Bayesian state estimators, such as Kalman filters, estimate states from noisy observations based on dynamical models. However, obtaining accurate models can be challenging when the system involves effects that are difficult to model faithfully, such as friction, impacts, and deformation in contact-rich manipulation. Uncertainty in system parameters, inputs, and disturbances, together with simplified noise models, can further introduce simulation-to-reality mismatch and degrade estimation accuracy. These limitations motivate learning a distribution over state trajectories conditioned on observations and controls without explicitly specifying the underlying physical models. We introduce NormFlowSDE, an amortized Bayesian state estimator that learns a distribution over state trajectories by combining neural stochastic differential equations with conditional normalizing flows. Its key design choice is to utilize the capability of normalizing flows to learn stochastic behavior of variables, while leveraging the continuous-time dynamics of SDEs to model the evolution of states over time. Once trained, the model draws state paths for new measurement sequences without per-sequence optimization. In addition, we connect NormFlowSDE to stochastic continuous-time dynamics by proving weak convergence of a mean-centered, drift-corrected inference scheme to an Itô diffusion under stated assumptions. Finally, we benchmark NormFlowSDE against direct estimators and learned particle filters based on normalizing flows on partially observed dynamical systems, including simulated systems and real-world robot datasets. The results show that NormFlowSDE attains the lowest estimation error with calibrated uncertainty intervals on both robot datasets and filters four times faster than the fastest particle filter on every dataset.", "published": "2026-11-20", "comment": "35 pages, 4 figures", "url": "https://arxiv.org/abs/2611.27362"}, {"id": "2602.07413", "title": "Going with the Flow: Koopman Behavioral Models as Pseudo Planners for Visuo-Motor Dexterity", "authors": ["Yunhai Han", "Jiaqi Fu", "Linhao Bai", "Ziyu Xiao", "Zhaodong Yang", "Yogita Choudhary", "Krishna Jha", "Chuizheng Kong", "Shreyas Kousik", "Harish Ravichandar"], "abstract": "Contemporary visuo-motor dexterity models often rely on expressive policy classes with diffusion and transformer backbones to achieve strong performance. However, these architectures require significant data and computational resources, and remain far from reliable, particularly for multi-fingered dexterity. Importantly, they model skills as reactive mappings and rely on fixed-horizon action chunking, creating a rigid trade-off between temporal coherence and reactivity. To address these issues, we first introduce Unified Behavioral Models (UBMs), a framework to represent dexterous skills as coupled dynamical systems that capture how visual features of the environment (visual flow) and proprioceptive states of the robot (action flow) co-evolve. As such, UBMs ensure temporal coherence by construction rather than heuristic averaging. Unlike world models that attempt to predict the impact of arbitrary robot actions on the environment, UBMs target behavioral dynamics that encode how demonstrated robot behavior is related to desired impacts on the environment. A UBM can be viewed as a pseudo planner: given an initial condition, it computes the desired robot behavior over the entire skill horizon, while simultaneously \"imagining\" the resulting flow of visual features. We propose Koopman-UBM as a first instantiation of UBMs in the form of a structured latent linear system. K-UBM's inherent structure enables reactivity and adaptation via automated online replanning: the model acts as its own runtime monitor, automatically triggering replanning when predicted and observed visual flow diverge beyond a threshold. Across seven simulated tasks and four real-world tasks, our approach performs comparably to state-of-the-art baselines, while offering considerably smoother executions, fast inference, efficient learning, robustness to occlusions, and automated online replanning.", "published": "2026-11-20", "comment": "Accepted by CoRL 2026. Website: https://k-ubm.github.io/", "url": "https://arxiv.org/abs/2602.07413"}, {"id": "2611.27817", "title": "BRINA: Bottom-Referenced Inertial Navigation with AKAZE, a Sonar SLAM for Autonomous Marine Vehicles", "authors": ["Adolfo Damiano Cafaro", "Patrizio Mariani", "Roberto Galeazzi"], "abstract": "Forward-looking sonar (FLS) provides reliable underwater perception where optical sensing is limited, but its use for navigation is hindered by the unobserved elevation of each return. As a result, motion estimated directly from sonar images suffers from an unknown metric scale that is commonly resolved using a Doppler velocity log (DVL). We present BRINA (Bottom-Referenced Inertial Navigation with AKAZE), a sonar-inertial SLAM system for marine vehicles that uses the FLS as its only exteroceptive sensor. BRINA estimates the sonar altitude from the first seabed return in each beam and uses it to project matched features onto the seabed, providing metric odometry without a DVL. We further derive a bound relating the remaining scale error to seabed tilt and slope variability. The method is evaluated in simulation with an autonomous underwater vehicle, and in field experiments with uncrewed surface vehicles over ten missions, using two FLS systems under different operating conditions.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.27817"}, {"id": "2608.19522", "title": "LF-GICP: Parameter-Free Degeneracy-Aware LiDAR Odometry via a Voxel-Normal Localizability Field", "authors": ["Eunsoo Im"], "abstract": "Scan-to-map LiDAR odometry drifts unboundedly along the unobservable axes of geometrically degenerate environments like tunnels and corridors, and existing degeneracy handling requires environment-specific parameter tuning. This paper presents a parameter-free approach. We show that in voxelized GICP the Gauss--Newton (GN) Hessian masks translational degeneracy, because covariance regularization keeps the translation block artificially well-conditioned. We bypass this with a regularization-free voxel-normal localizability field and two of its statistics: a normalized fraction $f_0$ detecting directional anisotropy, and an absolute per-voxel mass $λ_0$ distinguishing information absence (tunnels) from dilution (dense open scenes). A temporal-median gate combines both to trigger Fisher-information correspondence weighting. Calibrated once by fixed rules on two short sequences and then frozen, LF-GICP achieves the lowest KITTI relative translation error ($0.865\\%$) under an identical evaluation protocol against re-run baselines, outperforms them on GEODE tunnels and MulRan, leads the HeLiPR mean, and generalizes across four sensor types without re-tuning. We further demonstrate empirically that straight, uniform tunnels remain unobservable along their axis for LiDAR-only registration.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2608.19522"}, {"id": "2611.10566", "title": "Recursive Bayesian Monitoring of SLAM Failures for LiDAR-Based UAV Navigation", "authors": ["Mingqiao Han", "Qigeng Duan", "Xuchen Liu", "Jinqiang Cui", "Xi Chen", "Ben M. Chen"], "abstract": "SLAM failures remain difficult to avoid in autonomous robotic systems, and undetected failures can propagate to unsafe planning, control, and mission-level decisions. Existing monitoring strategies often depend on prior maps, estimator-internal variables, or redundant sensing, which limits their applicability to deployed and resource-constrained robots. This paper presents a scene-geometry consistency monitor for detecting geometry-manifested SLAM failures using only the geometric output of the SLAM backend. The targeted failures include cumulative drift-induced failures, abrupt misregistration failures, and backend map corruption when they become observable as inconsistency in reconstructed scene geometry. The proposed method represents revisited local regions with recursive latent voxel geometry and evaluates each current observation against a trusted continuation explanation and a weak non-propagated reference explanation. The resulting voxel-wise evidence contrasts are aggregated into a fixed-boundary monitoring signal for online failure declaration and downstream safety response. Experiments on self-collected sequences, GEODE benchmark sequences, multiple robotic platforms, and different SLAM backends show that the monitor responds to failures when they are manifested in backend scene geometry. It achieves 4/4 valid post-onset declarations with no pre-onset alarms on four self-collected sequences, detects geometry-manifested failures in all five corrupted GEODE runs while remaining alarm-free in five geometrically consistent runs, adds only 0.1--0.2\\% absolute CPU load, and supports a closed-loop UAV detect--isolate--recover workflow.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.10566"}, {"id": "2611.27181", "title": "HumanoidPose: Monocular 3D Pose Estimation for Humanoid Robots", "authors": ["Jinlin Gan", "Mingzhe Li", "Junsheng Zhang", "Zhibo Zhou", "Jiahan Geng", "Yuhua Luo", "Changwang Zhang", "Chenglu Wen", "Lan Xu", "Siqi Shen", "Cheng Wang"], "abstract": "As humanoid robots increasingly enter real-world environments, recovering their 3D whole-body pose from monocular imagery is becoming increasingly important for external state perception, motion analysis, and robot learning. However, Humanoid Robot Pose Estimation (HRPE) lies at the intersection of conventional Robot Pose Estimation (RPE) and Human Pose Estimation (HPE), while not being fully addressed by either paradigm: RPE primarily focuses on non-humanoid robots, particularly fixed-base manipulators, whereas HPE is built upon human-specific skeletal topologies, body models, and motion priors. Despite recent progress in humanoid 2D keypoint detection and HPE adaptation, humanoid-native 3D pose recovery remains insufficiently studied, and a dedicated benchmark with suitable training data and evaluation protocols is still lacking. To address this gap, we introduce Humanoids, a benchmark for monocular 3D humanoid robot pose estimation, and propose HumanoidPose, a framework for this task. Humanoids provides synthetic 3D supervision across diverse humanoid embodiments, manually annotated real-world 2D data, and real-world RGB sequences paired with robot states for 3D evaluation on a physical Roban humanoid. HumanoidPose combines human-inspired visual perception with robot articulation modeling and explicit kinematic grounding. Experiments on Humanoids and the DHRP-H1 benchmark demonstrate strong performance in articulation recovery and 3D pose estimation, including zero-shot transfer to real-world 2D and 3D evaluation. Ablation studies further show the contribution of robot-native articulation modeling and explicit kinematic grounding. The dataset and code will be publicly released to support future research in the community.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.27181"}, {"id": "2611.27289", "title": "InterBand-EMG: A Cross-Band Foundation Model for Generalizable Hand-Pose Estimation", "authors": ["Zongheng Guo", "Tao Chen", "Dalong Du", "Yijian Yang", "Heng Liu", "Lun Shu", "Chen Luo", "Junhao Tu", "Lei Shu", "Mingzhou Wu", "Yifan Liu", "Yu Zhang", "Zhenqiang Liu", "Shilei Wen", "Jie Zhou", "Manuela Ferrario"], "abstract": "Surface electromyography (sEMG) enables continuous hand-pose estimation, but learning representations that generalize across users and movements remains challenging. We introduce InterBand-EMG, which combines band-specific quantization with cross-band reconstruction and structured masked code prediction to learn transferable EMG representations for hand-pose tracking. We also introduce SynapMyo, an eight-channel EMG-to-pose dataset comprising 1,227.74 hand-hours from 499 users across 68 movement categories. Experiments on emg2pose and SynapMyo show that InterBand-EMG outperforms state-of-the-art baselines in joint-angle accuracy across all three generalization settings on both datasets. The source code and the SynapMyo dataset will be publicly released upon acceptance of this paper.", "published": "2026-11-20", "comment": "25 pages, 8 figures", "url": "https://arxiv.org/abs/2611.27289"}, {"id": "2611.27319", "title": "SAVIOR: Sample-efficient Adaptation of Vision-Language Models for OCR Representation", "authors": ["Akshata A Bhat", "Sharath Naganna", "Saiful Haq", "Prashant Khatri", "Krishna Chaitanya Reddy Tamataam", "Neha Arun", "Niyati Chhaya", "Pushpak Bhattacharyya"], "abstract": "Optical Character Recognition (OCR) pipelines and vision-language models exhibit high accuracy on standard OCR and document-understanding benchmarks, yet they systematically underperform on document patterns that are operationally critical in financial workflows. These patterns include vertical or rotated text, logo-embedded vendor names, fine-print regulatory clauses, degraded scans, and complex multi-column layouts. While underrepresented in public datasets, they constitute a substantial portion of real-world failure cases. We introduce SAVIOR, a sample-efficient data curation methodology that targets such high-impact failure scenarios to adapt vision-language models for robust financial OCR. We further propose PaIRS, a structure-aware evaluation metric that measures layout fidelity by comparing pairwise spatial relationships between tokens. Fine-tuning Qwen2.5-VL-Instruct with SAVIOR-Train achieves a word recall of 0.93. When the resulting layout-aware OCR output is used as context for document question answering, it attains an F1 score of 0.89, outperforming both open- and closed-source models such as GPT-4o, Mistral-OCR, PaddleOCR-VL, and DeepSeek-OCR.", "published": "2026-11-20", "comment": "Accepted to WACVW", "url": "https://arxiv.org/abs/2611.27319"}, {"id": "2611.27338", "title": "Latent Jacobian Steer: Eliciting Contact-Rich Out-of-Distribution Behaviors from Pretrained Humanoid Controllers", "authors": ["S K Swaminathan", "Shivam Sood", "Shreyansh Kansal", "Chengyang He", "Guillaume Adrien Sartoretti"], "abstract": "Given a pretrained general latent-conditioned whole-body humanoid controller, say a behavioral foundation model (BFM), how can we elicit complex and contact-rich out-of-distribution behaviors? Raw joint-action exploration enables direct, task-specific adjustments but can disrupt coordination learned by the pretrained controller, whereas latent exploration retains that coordination but is difficult to steer toward desired physical effects. To combine the complementary strengths of these exploration spaces, we propose Latent Jacobian Steer (LJS), which couples sampling in direct joint-action space with the semantics of the learned frozen controller's input latent space. For a task specified through desired physical effects, we sample task-relevant joint-action perturbations and map them through a damped local inverse of the policy Jacobian to obtain candidate latent ($z$) commands. These commands are executed through the frozen pretrained policy, while exploration is directed toward the physical outcomes required by the new task. Candidate outcomes are evaluated in simulation and composed into latent-command sequences that accomplish the task. Ablations show that neither action-space nor latent-space exploration alone provides the same capability as their coupling. Across diverse out-of-distribution tasks, simulation-based searching using this method produces contact-rich behaviors, including hurdling, manipulating articulated objects, and opening doors through non-prehensile contact. Over ten seeds, LJS completes more of each humanoid task than when searching in either space alone. Beyond humanoids, it also steers a goal-conditioned dexterous hand policy through four assembly tasks better than searching in goal space directly.", "published": "2026-11-20", "comment": "36 pages. Project page: https://latent-jacobian-steer.github.io/", "url": "https://arxiv.org/abs/2611.27338"}, {"id": "2611.27552", "title": "S-BFM: A Behavioral Foundation Model for Humanoid Control from Sparse Spatiotemporal Goals", "authors": ["Kun Yang", "Xuanyu Chen", "Jing Tan", "Yanjing Liu", "Yubo Zhao", "Renjing Xu", "Addison Lin Wang"], "abstract": "General-purpose whole-body trackers can execute diverse humanoid motions, but they require dense reference trajectories. However, tasks usually specify only where, in which posture, and when the robot should arrive, leaving the motion in between to a separate planner. Inspired by human motor coordination, our key idea is that a low-level controller can organize the intervening motion and its pace by itself from sparse goals with arrival times. In this paper, we propose S-BFM, a novel behavioral foundation model superior in its autonomy: it generates whole-body transitions from target postures, poses, and arrival times alone. Specifically, we first introduce Spatial Grounding, which adds world-frame position and heading to a forward-backward behavior representation through spatial reconstruction. Then, Time-Conditioned Distillation is designed to learn transitions and pace from real motion through closed-loop imitation of a dense-reference teacher. Lastly, Generative Fine-Tuning is introduced to broaden the covered distances and arrival times with a distilled motion generator. In simulation, S-BFM lowers global joint-position error by over 32% relative to the best baseline under fixed and mixed horizons, and raises fixed-goal reach from 43.5% to 74.6% while cutting terminal position error from 1.67 to 0.26 m. We further deploy S-BFM on the full-size AGIBOT A3 humanoid. Sparse spatiotemporal goals thus suffice for natural, well-timed whole-body motion.", "published": "2026-11-20", "comment": "11 pages, 7 figures, 4 tables", "url": "https://arxiv.org/abs/2611.27552"}]}, "rep": {"name": "三维表示与重建", "papers": [{"id": "2610.38951", "title": "GradSplat: Gradients Inside the Forward Pass for Feed-Forward 3D Gaussian Splatting", "authors": ["Jingong Chen", "Linlian Jiang", "Guangyuan Li", "Xinxin Zuo", "Yang Wang", "Chulwoo Pack", "Kyle Gao", "Kwanghee Won"], "abstract": "Feed-forward 3D Gaussian Splatting (3DGS) reconstructs a scene from a few images in a single pass, yet per-scene optimization on the same images can still improve its predicted Gaussians substantially. We show that refining the Gaussian shapes (scales and rotations) recovers nearly all of this improvement. Building upon this finding, we propose $\\textbf{GradSplat}$, a feed-forward model that performs gradient-conditioned Gaussian refinement within its forward pass, without requiring target views. It combines $\\textit{log-anisotropy correction}$, which changes the aspect ratios of each Gaussian at constant volume, with $\\textit{gradient-conditioned refinement}$, which feeds the gradient of the input-view loss to a learned recurrent update, first for opacity and color and then for the shape. GradSplat achieves the best PSNR and SSIM on RealEstate10K with input poses. Without input poses, it leads from $12$ views onward and, at six views, it only trails YoNoSplat, which, unlike GradSplat, requires ground-truth intrinsics. It also achieves the best results on DL3DV and the best PSNR and SSIM on ScanNet++ without fine-tuning. Project page: https://jingong-chen.github.io/GradSplat/", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2610.38951"}, {"id": "2609.31248", "title": "TailorGS: Made-to-Measure Density Control for 3D Gaussian Splatting", "authors": ["Afif Boudaoud", "Jiayi Liu", "Alexandru Calotoiu", "Torsten Hoefler"], "abstract": "3D Gaussian Splatting reconstructs a scene from a set of posed photographs called the capture; Gaussian count affects reconstruction quality, storage, and rendering cost. How to select this number automatically across capture scales remains unresolved: density control techniques effective on standard benchmarks can leave larger captures with too few Gaussians to reconstruct fine details. We observe that the surface to represent, given by capture extent and resolution, is known before training, whereas the capacity needed to reconstruct its content depends strongly on the 3D optimization trajectory and becomes apparent during reconstruction. We introduce TailorGS, which unifies coverage-scaled exploration and coverage-weighted self-distillation under a non-redundant 3D scene coverage measure. Before training, TailorGS groups observed surface points into coarse voxels and shares each voxel's weight among views observing it from the same side. Combined with image resolution, these weights set a generous exploration cap that limits budget inflation from repeated observations. During the first 80% of training, TailorGS grows toward this cap. The resulting model serves as teacher for a single closed-form self-distillation step, balancing fidelity to its renderings against Gaussian count under the same coverage measure. The retained primitives are refined over the remaining 20% of training. On 13 standard scenes, TailorGS matches the mean PSNR of the best-performing evaluated baseline, LeGS, with 48% fewer Gaussians. On eight large captures, the same configuration automatically scales to larger models when necessary, achieving the highest mean PSNR across 13 evaluated baselines: 0.63 dB above the runner-up by allocating 2.8 times as many Gaussians.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2609.31248"}, {"id": "2611.27407", "title": "BladeR: Scalable, Shape-Guided 3D Reconstruction of Wind Turbine Blades from UAV Imagery", "authors": ["Jonathan Sterckx", "Michiel Vlaminck", "Hiep Luong"], "abstract": "The structural integrity of wind turbine blades is critical for safe, efficient energy production. Accurate 3D reconstruction allows precise localization and quantification of wear and early damage detection. While drone-based inspections are standard, their high-resolution imagery poses challenges such as weak texture, lighting variability, and high computational cost. We present BladeR, a scalable pipeline for high-quality 3D reconstruction from inspection imagery. A hierarchical sparse reconstruction strategy leverages GPS/IMU data and blade shape priors to guide advanced keypoint matchers on full-resolution images. For dense reconstruction, a tiled Gaussian Splatting framework processes 45 MP images at native resolution, isolates the blade from background, and adaptively enhances detail recovery along the leading edge. Validation against commercial and open-source baselines shows significant improvements in model completeness and detail.", "published": "2026-11-20", "comment": "12 pages, 13 figures. Published at VISAPP 2026", "url": "https://arxiv.org/abs/2611.27407"}, {"id": "2611.27719", "title": "VeilGS: Solving Darkness as a Veil of 2D Basis Maps over Retinex 3DGS", "authors": ["Mohab Kishawy", "Chengzhou Tang", "Shahram Shirani", "Jun Chen"], "abstract": "In a dark capture, the darkness is not uniform. How much light reaches a surface depends on where it lies relative to the few light sources, and the camera compresses what remains with a tone curve. Most low-light 3D reconstruction methods either apply one curve to every pixel of a view, so a dark object beside a lamp and a bright one in an unlit corner receive the same correction, or store the darkness in the 3D representation, where it can absorb scene detail. We present VeilGS, a 3D Gaussian Splatting method for low-light novel view synthesis that treats the degradation as a veil drawn over a clear scene. Each Gaussian carries an albedo and a shading latent instead of spherical harmonics, separating surface colour from illumination. Each view is darkened by a spatially varying gain followed by a global tone curve, and rendering without this veil gives the restored scene. A small network predicts a coarse basis for the gain from the observation, and its coefficients are solved for each view rather than learned. Training through this solve discourages the Gaussians from absorbing what the veil can explain. VeilGS needs no paired normal-light supervision and stores no per-view parameters. On Gaussian-DK, its restored renders score best on no-reference NIQE and CLIP-IQA and are rated highest in a blind user study with 55 participants. On LOM, it achieves results competitive with the state of the art.", "published": "2026-11-20", "comment": "Project page: https://errorlogic1211.github.io/VeilGS/", "url": "https://arxiv.org/abs/2611.27719"}, {"id": "2610.36150", "title": "Any3R: Feedforward 3D Reconstruction from Any Camera Type", "authors": ["Jingong Chen", "Qingwen Zhang", "Youming Deng", "Chulwoo Pack", "Olaf Wysocki", "Boris Jutzi", "Kwanghee Won", "Kyle Gao"], "abstract": "Geometry foundation models recover camera poses and dense scene geometry from multiple images using feed-forward networks, but are typically designed for pinhole cameras. This assumption is embedded in the backbone itself: positional encoding locates each patch by its pixel index and the training loss weights every pixel equally, so both treat image coordinates as if they fixed the viewing direction in 3D space, which holds only for pinhole cameras. We condition both on the dense ray field, which maps each pixel to its 3D viewing direction and represents any central camera regardless of its projection model. $\\textit{Angular coordinates}$ use the viewing direction of each patch for positional encoding, and $\\textit{solid-angle weighting}$ scales the point loss by the angular area covered by each pixel. Together, they allow the same encoding and supervision to be used across different camera models. $\\textbf{Any3R}$ is therefore a feed-forward model that reconstructs from any mix of central cameras without lens-specific retraining. On a benchmark of eight central cameras across three datasets, where every method reconstructs with its own predicted camera poses, it is the most consistently accurate method. $\\textbf{Any3R}$ enables 3D reconstruction from crowdsourced and archival image collections containing diverse camera types. Project page: https://jingong-chen.github.io/Any3R/", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2610.36150"}, {"id": "2611.27060", "title": "Rethinking Cross-Sensor Domain Adaptation for Bridge Point Cloud Semantic Segmentation", "authors": ["Linghui Huang", "Zipeng Wang", "Shunjie Chen", "Peng Guan", "Jiandong Wang", "Siqing Li", "Luming Yang"], "abstract": "Segmentation models for bridge point clouds lose accuracy when trained on terrestrial laser scanning (TLS) data and applied to mobile laser scanning (MLS) data. This study re-examines the SemanticBridge TLS-to-MLS protocol to determine how sampling density, surface roughness, color, and acquisition viewpoint are expressed in the 8-cm sparse-voxel representation, and how adaptation gains depend on source-model convergence. Using one sparse-convolution U-Net, we combine raw-point statistics with controlled input perturbations and compare adaptive batch normalization, entropy minimization, Mean Teacher, and confidence-filtered self-training under 100- and 300-epoch schedules. TLS and MLS have similar nearest-neighbor spacing after preprocessing (12.08 and 12.02 mm), and a 4-mm perturbation of TLS points changes voxel occupancy by only 4.4%. Color distributions differ systematically, but zeroing color on identical voxels changes target mean intersection over union (mIoU) by only +0.02, and by +0.06 after the color augmentation is scale-corrected. The sensors also observe different portions of the bridge, yielding different class proportions. A 300-epoch source-only model obtains 57.80 mIoU on the paired-bridge protocol. Confidence-filtered self-training improves the 100-epoch baseline, but from a converged model it changes target mIoU by -0.97 (source-selected checkpoints) and -2.44 (final-50-epoch means). Repeated evaluation (standard deviation 0.27-0.64) and seed variation (1.88 across three seeds) are comparable to several method differences. Adaptation results on this benchmark therefore depend on representation scale, source-model convergence, and evaluation variability.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.27060"}, {"id": "2611.27281", "title": "GAAFormer: Geometry-Anchored Attention Transformer for Joint Point Cloud Denoising and Upsampling", "authors": ["Haoxi Tian"], "abstract": "Point cloud denoising and upsampling require samples that accurately recover the underlying surface from noisy or sparse observations. A central challenge in both tasks is preserving surface coverage while refining point locations. We introduce GAAFormer (Geometry-Anchored Attention Transformer), a unified generative octree transformer that performs both tasks with a shared network. Its decoder anchors attention neighborhoods to geometry, providing spatial context for occupancy prediction and point generation. Fixed voxel windows and alternating shifts preserve the grouping of surviving nodes as the output tree changes. The design retains the encoder, positional encoding, prediction heads, and parameter count of a serialized-attention backbone. We establish a deletion-consistency property of the neighborhood rule and evaluate both tasks using the same model. On PUNet, GAAFormer achieves a mean Chamfer distance (CD) of $6.0643\\times10^{-5}$, reducing CD and Hausdorff distance by 3.35% and 19.34%, respectively, relative to the serialized backbone. For upsampling, it achieves CD values of $0.8475$, $1.7057$, and $1.0147$ ($\\times10^{-5}$) on PU-GAN, PU1K, and Sketchfab, respectively, with improvements in CD, Hausdorff distance, and point-to-surface distance over the same backbone on PU-GAN and Sketchfab. These results establish a single architecture for point cloud denoising and upsampling. Within the shared encoder-decoder, the same geometry-anchored attention module improves both noise removal and dense point generation without task-specific redesign or additional parameters.", "published": "2026-11-20", "comment": "9 pages, 6 figures, 3 tables", "url": "https://arxiv.org/abs/2611.27281"}, {"id": "2611.27512", "title": "PGS-PCQA: Perceptually Gated Synthetic Supervision for No-Reference Point Cloud Quality Assessment", "authors": ["Qinyuan Fan", "Meng Zhang", "Clemens Gühmann"], "abstract": "Existing no-reference point cloud quality assessment (NR-PCQA) methods perform well within individual datasets but generalize poorly across datasets. We identify insufficient distortion coverage in training data as a key cause: on unseen distortion types, models rank severity levels near chance or even in reverse. We propose perceptually gated synthetic supervision for no-reference point cloud quality assessment (PGS-PCQA), an NR-PCQA model trained with synthetic distortion ranking. It builds a synthetic distortion bank from source reference point clouds and uses within-type severity ranking as supervision in addition to the source mean opinion scores (MOS), requiring no subjective scores for the synthetic samples. Since higher severity does not always mean lower perceived quality, a perceptual gate softens the ranking targets of pairs with small perceptual differences in rendered views. The synthetic supervision is used only during training and needs no target-domain data. In a single training run on SJTU-PCQA, PGS-PCQA achieves Spearman rank correlation coefficients (SRCCs) of 0.709 on WPC and 0.751 on BASICS. The corresponding published DSP-PCQA scores are 0.595 and 0.723. Under reference-disjoint cross-validation, PGS-PCQA achieves SRCCs of 0.955 on SJTU-PCQA, 0.934 on WPC, 0.906 on BASICS, and 0.791 on LS-PCQA Part I. In the exclusion experiment, the reported scores for the reduced synthetic bank represent 58-65% of the full-bank SRCC gain relative to training without the bank. Code is available at https://github.com/Fan-QY/PGS-PCQA.", "published": "2026-11-20", "comment": "15 pages (including supplementary material), 4 figures, 16 tables. Code: https://github.com/Fan-QY/PGS-PCQA", "url": "https://arxiv.org/abs/2611.27512"}, {"id": "2510.06470", "title": "Terrain-Aided Navigation Without Raycasting: A Sliding Grid Approach for Point Cloud Processing", "authors": ["Abdülbaki Şanlan", "Fatih Erol", "Murad Abu-Khalaf", "Emre Koyuncu"], "abstract": "We investigate the use of a point cloud measurement in terrain-aided navigation. Our goal is to aid an inertial navigation system, by exploring ways to generate a useful measurement residual for effective nonlinear state estimation. We compare two such measurement models that involve the scanning of a digital terrain elevation model: a) one that is based on typical ray-casting from a given pose, that returns the predicted point cloud measurement from that pose, and b) another computationally less intensive one that does not require raycasting and we refer to herein as a sliding grid. Besides requiring a pose, it requires the pattern of the point cloud measurement itself and returns a predicted point cloud measurement. We show that the sliding grid achieves comparable accuracy to raycasting, especially at higher altitudes, while being orders of magnitude faster computationally. By eliminating the need for raycasting, the sliding grid removes the dependency on dedicated GPU hardware or high-performance CPUs, making it well-suited for real-time terrain-aided navigation on resource-constrained embedded platforms.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2510.06470"}]}, "ff": {"name": "前馈几何（VGGT 一系）", "papers": [{"id": "2610.34845", "title": "PosePlaner: Denoising Any Feed-Forward Pose Predictor from Pairwise Planar Geometry", "authors": ["Yihang Chen", "Bin Tan", "Yujun Shen", "Yinghao Xu", "Nan Xue"], "abstract": "Recent multi-view Transformers (e.g., DUSt3R and VGGT) have advanced 3D reconstruction by scaling training data and model capacity from two views to many views and long sequences, subsuming the classical SfM/SLAM pipeline of feature extraction, matching, and pose estimation in a single feed-forward pass. Yet this subsumption hides the interfaces between pipeline stages---correspondences, geometry, and pose are entangled in a single forward pass, leaving supervised fine-tuning as the major path to improvement and offering no mechanism to correct predictions from geometric evidence at test time. We propose PosePlaner to close this gap by reviving the classical coupling between correspondences and pose via flow matching, treating pose refinement as a conditional generation problem that takes coarse geometric matches and initial pose as input condition and fuses the resulting pose hypotheses into a single refined estimate, providing a continuous, data-driven analog of RANSAC voting. Our method is trained efficiently on two-view data, yet serves as a periodic refiner for streaming n-view pose estimators with no retraining. Empirically, it corrects failures of feed-forward predictors, substantially improves correspondence-based solvers, and reduces accumulated drift in long streaming sequences.", "published": "2026-11-20", "comment": "Accepted at NeurIPS 2026. Project page: https://robbyant-research.github.io/PosePlaner/", "url": "https://arxiv.org/abs/2610.34845"}, {"id": "2611.27901", "title": "QuantStream3D: Geometry-Aligned Low-Bit KV Cache Quantization for Streaming Visual Geometry Transformers", "authors": ["Zunhai Su", "Keyu Fan", "Ruishan Guo", "Zhongzhu Zhou", "Jingzehua Xu", "Bohan Sun", "Hansen Feng", "Ruihan Hu", "Yik-Chung Wu", "Ngai Wong"], "abstract": "Streaming visual geometry transformers retain historical key-value (KV) states as cross-view geometric memory, but growing caches constrain long-sequence inference. We systematically characterize KV quantization in streaming geometry and uncover two linked challenges: Nonuniform Geometric Sensitivity and Cache-Geometry Mismatch. Quantization sensitivity varies across precision choices and cache locations, while perturbed retrieval changes geometry-head inputs and propagates through subsequent predictions and KV writes. Guided by these findings, we propose QuantStream3D, to our knowledge the first dedicated KV quantization framework for streaming visual geometry transformers. Geometry-Guided Mixed-Precision KV Quantization protects sensitive cross-view evidence, while Geometry-Aligned Quantization-Aware Distillation jointly adapts transformer blocks and geometry heads on student-generated quantized history. Across five benchmarks and two backbones, QuantStream3D achieves near-lossless geometric accuracy in most settings with predominantly 2-bit KV caches, and many configurations surpass unquantized inference. Compared with LLM-oriented KV quantizers, it reduces TUM absolute trajectory error and NeuralRGBD completeness error by up to 57.4% and 69.7%, respectively. Integration with existing native cache-pruning methods further pushes compression while improving reconstruction quality on NeuralRGBD. Our optimized StreamVGGT backend achieves $5.05\\times$ physical KV compression and 23.1% lower latency at batch size one. Under a fixed memory budget on the same GPU, it supports $5.4\\times$ the maximum batch size and up to $1.67\\times$ the peak throughput of unquantized inference. Code and pretrained checkpoints will be made publicly available.", "published": "2026-11-20", "comment": "19 pages, 5 figures. Includes appendix", "url": "https://arxiv.org/abs/2611.27901"}, {"id": "2609.08848", "title": "FIRE3D: Feed-forward Interactive 3D Scene Reconstruction Within A Minute", "authors": ["Hongchi Xia", "Tianhang Cheng", "Wei-Chiu Ma", "Shenlong Wang"], "abstract": "We present FIRE3D, a unified framework that transforms a single RGB image or casual video into interactable 3D scene assets for games and interactive applications in under a minute for up to twelve textured instances including preprocessing. At the core of FIRE3D is a feed-forward inference pipeline that predicts a compositional scene representation from posed RGB-D observations estimated from the RGB capture, including the 6-DoF pose, bounding box, mesh, and texture for detected objects. By modeling the scene as a collection of discrete entities, FIRE3D produces amodal object assets that can be independently edited and used in interactive applications. Our framework requires no test-time optimization, runs substantially faster than the compared reconstruction systems, and provides object-level completeness beyond existing feed-forward 3D approaches. We demonstrate leading detection accuracy, strong geometry reconstruction, and competitive rendering quality on the evaluated benchmarks, with substantial runtime gains.", "published": "2026-11-20", "comment": "Project page: https://xiahongchi.github.io/Fire3D/", "url": "https://arxiv.org/abs/2609.08848", "summary": "针对从单张RGB图像或随手拍视频生成游戏等交互应用的仿真就绪3D资产，提出统一前馈框架FIRE3D：从RGB估计的RGB-D观测预测组合式场景表示，输出各物体的6-DoF位姿、包围盒、网格与纹理，场景建模为物理解耦的可交互实体集合，无需测试时优化。在位姿、几何与纹理上具竞争力或达SOTA，且比已有可交互方法快数个数量级。"}, {"id": "2611.27621", "title": "Automating Multi-View Quality Assessment of 3D Annotation Layouts", "authors": ["Hongyi Yang", "Jinao Wu", "Yanwei Zhang", "Shengwen Fu", "Haibin Ling", "Bingyao Huang", "Jingwei Qu"], "abstract": "Text labels provide descriptive information about elements in visual scenes. In 3D visualization, the arrangement of these labels and their connections to target locations forms an annotation layout. Assessing layout quality supports comparisons between alternative layouts. However, existing quality measures often focus on specific layout properties and may not fully reflect human judgments of overall quality. Moreover, a layout may appear clear from one viewpoint but suffer from occlusion or clutter from another. To address these issues, we propose a multi-view quality assessment method based on a multimodal large language model (MLLM). We fine-tune a compact MLLM using structured supervision from human ratings to predict a rating for each quality dimension in each view. These ratings are aggregated into view-level and sample-level quality scores. To support training and evaluation, we construct the Annotation Layouts with Quality Assessment (ALQA) dataset, containing 3,216 layout samples from 1,072 3D objects across 13 categories. Each layout is rendered from 5 predefined viewpoints, and each view is independently rated by 3 human raters across 5 quality dimensions. On ALQA, our method agrees more closely with human reference scores than the evaluated MLLM baselines, and a user study demonstrates strong agreement with human preferences in layout ranking.", "published": "2026-11-20", "comment": "11 pages, 5 figures", "url": "https://arxiv.org/abs/2611.27621"}, {"id": "2611.27822", "title": "Underwater Spectral Recovery via Multi-View Hyperspectral Imaging", "authors": ["Jonathan Sterckx", "Alice James", "Avishkar Seth", "Laurens Diels", "Michiel Vlaminck", "Jan Aelterman", "Endrowednes Kuantama", "Hiep Luong"], "abstract": "Underwater imaging suffers from wavelength-dependent absorption and scattering that distort scenes and obscure spectral signatures. While RGB restoration improves visual clarity, the outputs remain broadband and tied to the sensor's color space. We introduce a physically grounded framework that lifts underwater restoration to continuous spectral radiance using multi-view hyperspectral imaging. By representing continuous spectra via low-rank basis functions and leveraging multi-distance observations, our framework jointly constrains scene radiance and water parameters. We employ a robust sparse-to-dense pipeline: water parameters are estimated from consistent multi-view matches and then applied globally to invert the light transport model across the full images. Validated on physics-based synthetic data rendered via the Mitsuba 3 spectral path tracer, our method recovers physically meaningful radiance spectra and, as a downstream application, outperforms standard image restoration baselines.", "published": "2026-11-20", "comment": "Preprint. Code and data can be shared upon publication. 27 pages (15 main, 12 appendix), 12 figures", "url": "https://arxiv.org/abs/2611.27822"}]}, "wm": {"name": "世界模型", "papers": [{"id": "2610.39232", "title": "GenSight: Unified Video Generation and 4D Perception for Embodied World Modeling", "authors": ["Haitang Feng", "Zhuoman Liu", "Zhennan Wang", "Sheng Wang", "Juelin Li", "Chengzhi Zhao", "Hexiang Wei", "Lin Shao"], "abstract": "Embodied world models should not only imagine plausible futures, but also perceive the geometric, semantic, and motion structure of the evolving world. We present GenSight, a unified embodied world model that brings future video generation and dense perception into a single pretrained video diffusion transformer. GenSight uses a unified spatiotemporal representation for video, depth, embodiment segmentation, and first-frame-relative 2D flow. Built on a shared DiT backbone, GenSight uses lightweight task modulation to predict all modalities within the same architecture. All tasks are jointly optimized within a unified velocity prediction space. At inference, GenSight supports two complementary modes: multi-step future video generation with aligned dense predictions and single-step dense perception from an observed video. By unifying modality representation, model architecture, and prediction space, GenSight avoids separate modality-specific pipelines and couples appearance, geometry, semantics, and motion in a shared representation. It promotes cross-modal consistency and allows dense perception to benefit from the spatiotemporal priors learned through video generation. Trained on embodied manipulation data spanning multiple robot embodiments and human-hand interactions, GenSight demonstrates strong performance in both video generation and dense 4D perception, highlighting the effectiveness of unifying seeing and imagining for embodied world modeling.", "published": "2026-11-20", "comment": "Project page: https://roboscience-ai.github.io/gensight-page/", "url": "https://arxiv.org/abs/2610.39232"}, {"id": "2611.08156", "title": "La-JEPA: Compact Robot Policies with Latent World Modeling", "authors": ["Mateo Clémente", "George Z. Xue", "Amin Abyaneh", "Liheng Ma", "Rui Heng Yang", "Tongtong Cao", "Zhanguang Zhang", "Yingxue Zhang"], "abstract": "World-action models adapt pretrained video generators, and vision-language-action models build on vision-language backbones, tying policy architecture and inference cost to large transformers designed for generation rather than control. While recent world-action models mostly scale the video backbone and its data, we argue that the choice of latent space is just as critical, and that the policy should be trained natively in that space. We introduce Latent Action JEPA (La-JEPA), a compact world-action model whose policy transformer is trained from scratch in the feature space of a pretrained V-JEPA 2.1 encoder; it predicts future features with actions during training and generates only actions at inference. Among policies without embodied pretraining, La-JEPA achieves state-of-the-art average RoboTwin 2.0 success under both clean-only and full training, and state-of-the-art LIBERO-Plus success with corrected instructions, while using far fewer parameters than the strongest competitors; with full training, its success scales with model size up to 2.1B. Its S and B policies run two to five times faster than Fast-WAM and Faster-WAM while outperforming both on LIBERO-Plus and RoboTwin 2.0, and La-JEPA outperforms the closest JEPA-based methods, LeapBot-WA and JEPA-WAM, without their pretrained policy backbones. On four real-robot tasks, its average success is comparable to $π_{0.5}$. A design study shows that JEPA features outperform video VAE latents, most clearly out of distribution, and that training-time future prediction improves the policy even when skipped at inference. Tailoring the policy's design, including its latent space, to control can thus matter more than the knowledge transferred from a pretrained generative backbone, suggesting that robot foundation models may benefit from architectures designed for control rather than inherited from generation.", "published": "2026-11-20", "comment": "31 pages, 6 figures. v2: full-RoboTwin results with scaling to 2.1B parameters, leave-one-out ablation, revised figures and text. Code: https://github.com/mt-clemente/lajepa", "url": "https://arxiv.org/abs/2611.08156"}, {"id": "2611.27963", "title": "Non-penetrating World Models", "authors": ["Yuhang Dai", "Yinwei Wu", "Ziyue Lin", "Han Ji", "Xingyi Yang"], "abstract": "We study a new problem of preventing object penetration in interactive video world models. To understand how existing models handle this, we introduce NoPeBench, a benchmark that evaluates how world models respond to physical obstacles. Our evaluation reveals that none of the open-source models can reliably prevent such failures. Surprisingly, however, these models already encode the information needed to predict such violations. We find that the hidden states of diffusion transformers (DiTs) can predict whether a candidate action will penetrate an obstacle. Building on this, we introduce NoPeWorld, a lightweight framework that detects and prevents penetration. Specifically, we train a small prediction head on top of a frozen DiT's hidden states to read out if a candidate action is safe or not. Unsafe actions are then replaced with safe ones that best preserve the original intent. Despite its simplicity, NoPeWorld substantially reduces the physical violation rate, averaged over six video world models, from 74% to 16%. Remarkably, our method shows zero-shot generalization to open-domain imagery, third-person viewpoints, and moving obstacles. We publicly release our code, the NoPeBench benchmark, and model weights. Project Page: https://nopeworld.github.io .", "published": "2026-11-20", "comment": "20 pages, 13 figures. Code: https://github.com/yuhangdai427/NoPeWorld", "url": "https://arxiv.org/abs/2611.27963"}, {"id": "2602.14027", "title": "Train Short, Inference Long: Training-Free Horizon Extension for Autoregressive Video Generation", "authors": ["Jia Li", "Xiaomeng Fu", "Xurui Peng", "Weifeng Chen", "Youwei Zheng", "Tianyu Zhao", "Jiexi Wang", "Fangmin Chen", "Xing Wang", "Hayden Kwok-Hay So"], "abstract": "Autoregressive (AR) video diffusion models such as CausVid and Self Forcing enable efficient long-video generation through chunk-wise rollout with local sliding-window attention, yet suffer from visual degradation, appearance drift, and motion collapse beyond their training horizons. From a long-context sequence modeling perspective, we identify two underexplored inference-time bottlenecks in AR video length extrapolation. First, scarce high-quality long-video data and high training costs restrict video models to short training horizons. Consequently, low-frequency dimensions of 3D temporal RoPE remain under-exposed during training, inducing stronger spectral bias than in LLMs and hindering direct transfer of LLM context-extension methods. Second, both standard independent noise initialization and consistency-oriented methods with positive inter-frame correlation lack high-frequency dynamic priors to counter motion decay over long rollouts. To address these issues, we propose FLEX (Frequency-aware Length EXtension), a training-free, plug-and-play inference framework comprising three complementary components. Frequency-aware 3D RoPE modulation interpolates under-exposed low frequencies while extrapolating well-exposed high frequencies. Antiphase Noise Sampling (ANS) introduces negative intra-chunk correlation to inject high-frequency motion priors at initialization. An inference-only attention sink works with RoPE modulation to anchor global consistency. Experiments on Self Forcing and CausVid show substantial gains in long-horizon synthesis, with Self Forcing + FLEX matching or surpassing both training-free and training-based baselines on VBench-Long at $6\\times$ to $12\\times$ length extrapolation. Additional evaluations on Krea-14B and minute-level generation with LongLive demonstrate strong generalization across model scales, inference pipelines, and native long-video generators.", "published": "2026-11-20", "comment": "18 pages, 15 figures", "url": "https://arxiv.org/abs/2602.14027"}, {"id": "2610.32965", "title": "RynnUnify: Towards Unified Embodied Brain", "authors": ["Minghao Zhu", "Bohan Hou", "Kun Xiang", "Zixuan Wang", "Yinzhou Tang", "Yifei Yang", "Zhikai Wang", "Tianyi Zhang", "Kehan Li", "Haoyu Zhao", "Siteng Huang", "Leigang Qu", "Sicong Leng", "Dongchi Huang", "Xiao Lin", "Ronghao Dang", "Mingxiu Chen", "Shijian Lu", "Yue Wang", "Xiaodan Liang", "Zhenyu Zeng", "Deli Zhao", "Chengju Liu", "Jianfei Yang", "Xin Li"], "abstract": "We introduce RynnUnify, a 16B unified embodied model that combines strong embodied understanding with long-horizon visual planning through interleaved video--language reasoning. With capabilities spanning spatial reasoning, physical prediction, and grounding, RynnUnify connects an understanding of the physical world with visual anticipation of how it evolves across successive subtasks. Building on these capabilities, we further develop an agentic extension through reinforcement learning to selectively use video predictions for reasoning about unobserved states and interaction outcomes. We also develop a world-action extension of the full RynnUnify model, translating its understanding and prediction capabilities into robot control. To evaluate these capabilities, we introduce Rynn-VP and Rynn-GEU for long-horizon visual planning and anticipatory reasoning. Experiments show that RynnUnify achieves the highest average embodied understanding score among the evaluated unified multimodal models and improves the Rynn-VP overall score by 9.75 points over Cosmos 3 Nano. Its agentic extension improves the Rynn-GEU average by 6.0 points over direct reasoning, while the world-action extension achieves 51.5\\% success on 20 selected composite RoboCasa365 tasks and 46.7\\% average success across three real-robot tasks. Together, these results establish RynnUnify as a shared foundation for embodied understanding, visual planning, and robot control, taking a step toward a unified embodied brain.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2610.32965"}, {"id": "2611.22717", "title": "PCRG: Training-Free Pruning and Caching of Reference Tokens for Video Generation", "authors": ["Siyuan Wang", "Haoran Li", "Yi Yue", "Tak L. Fung", "Quan Chen"], "abstract": "Reference-to-video diffusion transformers pack the variational autoencoder (VAE) latents of all references and the generated tokens into one full-attention sequence, in which reference tokens make up about half. Because attention cost grows quadratically with sequence length, these tokens take up an even larger share of the attention computation, yet most of them are static, smooth or irrelevant to the output. To accelerate reference-conditioned generation, we propose pruning and caching of reference tokens for video generation (PCRG), a training-free, plug-and-play method that uses two signals the model already computes to assign each reference token to one of three tiers, namely pruned, cached or kept. The first is a low-level redundancy r from VAE latents, since a token whose latent barely changes over time or across its neighbors adds little new content. The second is a high-level importance g from the vision-language-model (VLM) conditioner, where the attention that the prompt and any first or last frames pay to a token tells whether the output needs to read it. Tokens that are not redundant are kept, and redundant tokens are cached if important and pruned otherwise. Pruned tokens leave the sequence before the first step with all rotary position embedding positions unchanged. Cached tokens have their keys and values computed once and reused, and kept tokens are processed as usual. On MiniMax-H3, already distilled to 8 timesteps and quantized to int8, PCRG is 1.57x faster end to end on our V2V-Bench and 1.49x faster on the public VACE-Benchmark, while the quality of VBench drops by only 0.24% and 0.17%, respectively. PCRG shortens the sequence rather than changing how attention is computed or which steps are run, so it also stacks on step caching and sparse attention. On V2V-Bench it reaches 1.86x with TeaCache, 1.82x with Spark at nearly unchanged fidelity and 2.15x with Veda.", "published": "2026-11-20", "comment": "11 pages, 5 figures. Project page: https://anorak-games.github.io/pcrg/", "url": "https://arxiv.org/abs/2611.22717"}, {"id": "2611.26981", "title": "ViewDreamer: A Robot World Model beyond Fixed Camera Setups", "authors": ["Ye Mao", "Jinhui Xiong", "Egor Larionov", "Shiyang Lu", "Krystian Mikolajczyk", "Wei Ye"], "abstract": "Video generation models are increasingly important for robot learning, yet most generate each camera view separately or tile all views in a fixed layout. Robot demonstrations, however, are captured by synchronized cameras whose number, placement, and order vary across embodiments. We present ViewDreamer, a single world model that handles variable sets of cameras by disentangling per-view generation from cross-view interaction. Each view follows the generation path of a pretrained single-view model, and views interact only through shared slot tokens. We stabilize multi-view training with a curriculum that gradually increases the number of views. Cross-View Slot Agreement uses visual foundation models to group geometrically and semantically similar regions across views into shared slots. On RoboView-Bench, which covers one to four cameras, ViewDreamer achieves the best generation quality among the models evaluated and improves cross-view consistency over independent per-view generation. These gains carry over to our world-action model (WAM) and action-conditioned world model (AC-WM). Our WAM outperforms the FastWAM-Joint baseline on LIBERO-Plus, RoboTwin 2.0, and RoboDojo, and on a real Franka robot. Both variants improve out-of-domain generalization to various camera settings and scenes.", "published": "2026-11-20", "comment": "29 pages, 13 figures, 21 tables. Project page: https://matchlab-imperial.github.io/ViewDreamer/", "url": "https://arxiv.org/abs/2611.26981"}, {"id": "2611.27024", "title": "ReactDrive: Self-Reactive Driving World Model", "authors": ["Yifan Wang", "Xiaoqi Wang", "Cho-Ying Wu", "Wenbin He", "Chenyu You", "Liu Ren"], "abstract": "The world evolves through the dynamics of its constituent entities and their interactions, with changes in one entity influencing the behavior of others. To simulate this evolution under different actions, interactive world models need to capture the resulting agent responses as part of the world's own dynamics. In autonomous driving, errors in modeling these responses can misrepresent maneuver safety and undermine the reliability of generated videos used for policy evaluation and learning. To formalize this intrinsic requirement for driving world model, we define self-reactivity as the capability to model agent responses from observed history and a specified ego action, and generate visual futures that reflect those responses without prescribed future agent trajectories. To realize this capability, we introduce ReactDrive, a driving world model that jointly learns agent dynamics and visual generation through a shared agent state representation. Within this framework, dynamics supervision grounds a reactive dynamics prior in observed agent states, while the video objective jointly optimizes the self-reactivity and visual realism. Experiments show improved agent responses, ego controllability, and video quality, a 96.0% preference for agent reactivity in human comparisons across five baselines, and better downstream planning through augmentation with generated videos. We hope this work encourages the community to recognize self-reactivityas a foundational capability for developing and evaluating interactive world models. Project page: https://reactdrive.github.io/ .", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.27024"}, {"id": "2611.27124", "title": "A Plan or an Adversarial Example? A Round-Trip Check for Latent World Models", "authors": ["Huiyuan Tian", "Chih-Yung Wen", "Shijian Li"], "abstract": "If we optimize an image until a classifier is confident it shows a cat, we may get an adversarial example, not a cat. Planning with a latent world model is a similar search for actions whose predicted future is closest to the goal. Is the result a plan, or an adversarial example of the world model? We show that it can be either. On the released DINO-WM and LeWM, more iterations of the cross-entropy method (CEM) lower the predicted cost but lose up to half of the problems CEM had already solved. The model's own predictions do not reveal these failures. We propose a simple test that executes the plan after every iteration and counts the problems a planner solves and then loses. Unlike an image, a plan comes with its actions, which our round-trip check reads back from the predicted states with a small network, penalizing mismatches. The check reads back the sum of each block of five actions, the part that two consecutive predicted states determine. Without retraining the world model and at only 0.2% to 3.1% more planning time, it improves the widely used planners CEM and MPPI on three released world models, and gains more where planners lose more problems. Without replanning, success rises from 0.39 to 0.76 on Wall with DINO-WM and from 0.56 to 0.94 for MPPI on JEPA-WM. With replanning (MPC), it rises from 0.70 to 0.81 on Cube with LeWM.", "published": "2026-11-20", "comment": "12 pages, 5 figures, 8 tables", "url": "https://arxiv.org/abs/2611.27124"}, {"id": "2611.27173", "title": "PACE-WM: Parallel World Modeling with Action History for Visual Planning", "authors": ["Haishan Liu", "Shijie Lian", "Bin Yu", "Yao Zhang", "Changti Wu", "Fanping Liu", "Jianzheng Liu", "Lei Xie", "Cong Huang", "Kai Chen"], "abstract": "JEPA-style world models support visual planning by predicting future representations conditioned on future actions. However, similar observations can conceal different motion states, making temporal context essential for interpreting future action effects. We propose PACE-WM, a parallel world model that uses executed-action history to contextualize future prediction and planning. Specifically, PACE-WM maintains a recurrent memory of executed actions and uses this memory to condition a causal Transformer. PACE-WM predicts multiple future representations in parallel without recursive predicted-state feedback within each prediction window. We further introduce Reference-Anchored Minimum Progress (RAMP) for action selection during planning. RAMP scores candidate actions by their predicted goal improvement along direct and split paths relative to a shared reference. Across four visual planning tasks, PACE-WM with RAMP achieves an average success rate of $98\\%$ and plans approximately $7$-$9\\times$ faster than autoregressive LeWM under matched CEM settings. We also construct four controlled benchmarks to evaluate PACE-WM's capabilities in motion disambiguation, goal-relative motion, and goal adaptation. Project page is available at https://github.com/LHS180/PACE-WM.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.27173"}, {"id": "2611.27344", "title": "Learning Interaction Dynamics via Motion-Region Guidance for Robotic Video World Models", "authors": ["Yongkang He", "Xiaofen Xing", "Xiangmin Xu"], "abstract": "Action-conditioned video world models imagine future observations under candidate robot actions, providing a promising visual tool for robot policy evaluation and interaction simulation. However, existing video world models often optimize global reconstruction errors instead of emphasizing interaction-relevant regions. As a result, they may preserve overall scene appearance but overlook local interaction details, leading to physically implausible outcomes such as hallucinated contact effects and inconsistent robot-object interactions. We introduce MoReWorld, a unified motion-region-guided framework that uses a shared motion region, the part of the environment that moves in response to the robot's actions, to focus dynamics learning and video generation on interaction-relevant regions. The same motion region guides local motion prediction, region-aware supervision, and motion-gated future-feature conditioning. At inference time, the motion region is predicted as a motion probability map from visual history and robot actions, without requiring future observations or ground-truth motion labels. On WorldSimProbe, MoReWorld achieves the highest overall simulator-faithfulness score, with the strongest performance on local consistency, global consistency, and interaction dynamics. These results indicate that motion-region guidance helps the model preserve scene-level consistency while more faithfully predicting action-conditioned interaction dynamics.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.27344"}, {"id": "2611.27418", "title": "Beyond Future Views: Exploring Future-State World Models for Vision-Language Navigation", "authors": ["Kangyi Wu", "Pengna Li", "Yucheng Wang", "Yance Fang", "Xihan Ma", "Zhizhong Su", "Yang Wu", "Ye Deng", "Jinjun Wang", "Jianyi Liu"], "abstract": "Vision-Language Navigation(VLN) requires an embodied agent to follow language instructions through unseen 3D environments, where the target spaces often lie beyond the current observation. Navigation world models address this challenge by predicting future views either as pixels or latent representations, providing valuable look-ahead information for action decision. Both paradigms define the future primarily through what the agent may observe, raising a fundamental question: is predicting future views the ultimate form to represent the future for VLN? Cognitive studies show that the human hippocampus prospectively represents both future goals and intervening locations along planned routes. Inspired by this predictive-map view, we organize the navigation-relevant future around goal-directed spatial states and route structure. We instantiate this perspective with two complementary abstractions: a short-horizon waypoint that specifies the next local state to reach, and a mid-horizon corridor that captures the spatial support of the upcoming route. Based on this design, we propose FS-Nav, a future-state world modeling framework that predicts waypoint-corridor states from spatial memory and language instructions, and communicates them to a VLM navigator through top-down and first-person interfaces. Experiments on standard VLN benchmarks demonstrate that FS-Nav achieves state-of-the-art performance. This highlights navigation-relevant future-state modeling as a promising direction for representing the future in VLN.", "published": "2026-11-20", "comment": null, "url": "https://arxiv.org/abs/2611.27418"}]}}};
